// Decryption function (simplified):
function decode(response) {
  // If skipDecode is true, skip
  if (1 !== params.envvv || t.skipDecode || ['blob','arraybuffer'].includes(t.responseType)) {
    // skip decoding
  }

  // The actual decode:
  // 1. Reverse the string
  let t = "";
  for (let s = e.length - 1; s >= 0; s--) t += e[s];

  // 2. Base64 decode
  const o = atob(t);

  // 3. Convert to Uint8Array
  const n = new Uint8Array(o.length);
  for (let e = 0; e < o.length; e++) n[e] = o.charCodeAt(e);

  // 4. Text decode
  const a = (new TextDecoder).decode(n);

  // 5. Parse as JSON
  return JSON.parse(a);
}
